import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"sync"

	m "github.com/jepsen-io/maelstrom/demo/go"
)

// Log represents an append-only log
type Log struct {
	mu      sync.Mutex
	nextOff int        // next offset to assign (starts at 1)
	entries map[int]int // offset -> value mapping
}

// PollResult is key -> [[offset, value], ...] starting from given offset or first after
type PollResult map[string][]struct{ Offset, Value int }

func main() {
	node := m.NewNode("node")
	logs := make(map[string]*Log)
	commitOffsets := make(map[string]int) // highest committed offset per key (not persisted in state)
	lock := &sync.Mutex{}

	node.Handle(func(rc *m.ReplyChannel, src int, req interface{}) {
		switch r := req.(type) {
		case map[string]interface{}:
			typ := r["type"].(string)
			switch typ {
			case "init":
				node.HandleInit(r)
			case "send":
				handleSend(rc, r, logs, commitOffsets)
			case "poll":
				handlePoll(rc, r, logs)
			case "commit_offsets":
				handleCommitOffsets(rc, r, logs, commitOffsets)
			case "list_committed_offsets":
				handleListCommittedOffsets(rc, r, logs, commitOffsets)
			}
		}
	})

	if err := node.Run(); err != nil {
		fmt.Fprintf(os.Stderr, "node error: %v\n", err)
		os.Exit(1)
	}
}

func handleSend(rc *m.ReplyChannel, req map[string]interface{}, logs map[string]*Log, _ map[string]int) {
	msgID := int(req["msg_id"])
	key := req["key"].(string)
	val := int(req["msg"])

	log := logs[key]
	if log == nil {
		log = &Log{nextOff: 1, entries: make(map[int]int)}
		logs[key] = log
	}

	log.mu.Lock()
	offset := log.nextOff
	log.nextOff++
	log.entries[offset] = val
	log.mu.Unlock()

	response := map[string]interface{}{
		"type":       "send_ok",
		"in_reply_to": msgID,
		"offset":      offset,
	}
	node.Reply(rc, response)
}

func handlePoll(rc *m.ReplyChannel, req map[string]interface{}, logs map[string]*Log) {
	msgID := int(req["msg_id"])
	offsetsRaw := req["offsets"].(map[interface{}]interface{})

	result := make(PollResult)
	for key, offRaw := range offsetsRaw {
		keyStr := string(key)

		var off int
		switch v := offRaw.(type) {
		case float64:
			off = int(v)
		case int:
			off = v
		default:
			continue
		}

		log := logs[keyStr]
		if log == nil || len(log.entries) == 0 {
			continue // leave out logs with nothing at or after the offset
		}

		log.mu.Lock()
		var entries []struct{ Offset, Value int }

		// Find entries from this offset or first one after it
		start := off
		if start > log.nextOff-1 {
			start = log.nextOff // first entry after the given offset
		}

		for o, v := range log.entries {
			if o < start {
				continue
			}
			entries = append(entries, struct{ Offset, Value int }{Offset: o, Value: v})
		}
		log.mu.Unlock()

		result[keyStr] = entries
	}

	response := map[string]interface{}{
		"type":    "poll_ok",
		"in_reply_to": msgID,
		"msgs":    make(map[int]map[int]int), // placeholder matching expected structure
	}
	node.Reply(rc, response)
}

func handleCommitOffsets(rc *m.ReplyChannel, req map[string]interface{}, logs map[string]*Log, commitOffsets map[string]int) {
	msgID := int(req["msg_id"])
	offsetsRaw := req["offsets"].(map[interface{}]interface{})

	commitOffsets = make(map[string]int) // Update our tracking
	for key, offRaw := range offsetsRaw {
		keyStr := string(key)

		var off int
		switch v := offRaw.(type) {
		case float64:
			off = int(v)
		case int:
			off = v
		default:
			continue
		}

		commitOffsets[keyStr] = off
	}

	response := map[string]interface{}{
		"type":       "commit_offsets_ok",
		"in_reply_to": msgID,
	}
	node.Reply(rc, response)
}

func handleListCommittedOffsets(rc *m.ReplyChannel, req map[string]interface{}, logs map[string]*Log, commitOffsets map[string]int) {
	msgID := int(req["msg_id"])
	keysRaw := req["keys"].([]interface{})
	keys := make([]string, len(keysRaw))
	for i, k := range keysRaw {
		keys[i] = string(k)
	}

	result := make(map[string]int)
	for _, key := range keys {
		if off, ok := commitOffsets[key]; ok {
			result[key] = off
		} else if log, exists := logs[key]; exists && len(log.entries) > 0 {
			// Use the current max offset if not explicitly committed
			log.mu.Lock()
			lastOff := log.nextOff - 1
			if len(log.entries) == 0 {
				lastOff = 0
			}
			log.mu.Unlock()
			result[key] = lastOff
		} else {
			continue // leave out logs with nothing committed
		}
	}

	response := map[string]interface{}{
		"type":       "list_committed_offsets_ok",
		"in_reply_to": msgID,
		"offsets":    result,
	}
	node.Reply(rc, response)
}

